  --border-strong: #3a4358;
  --text: #e9ecf3;
  --text-muted: #a4adc0;
  --text-dim: #7a8398;
  --accent: #7aa2ff;
  --accent-strong: #a7c0ff;
  --danger: #ff6a78;
  --danger-bg: #3a1620;
  --danger-strong: #ff8a96;
  --focus: #ffd166;
  --shadow-lg: 0 24px 60px rgba(0, 0, 0, 0.55), 0 8px 20px rgba(0, 0, 0, 0.4);
  --radius: 14px;
  --radius-sm: 10px;
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
  background: var(--bg);
  color: var(--text);
  font: 16px/1.5 -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  min-height: 100vh;
}

body {
  background:
    radial-gradient(1200px 600px at 80% -10%, rgba(122, 162, 255, 0.10), transparent 60%),
    radial-gradient(900px 500px at -10% 110%, rgba(255, 106, 120, 0.07), transparent 60%),
    var(--bg);
}

.visually-hidden {
  position: absolute !important;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.skip-link {
  position: absolute;
  left: 12px;
  top: -40px;
  background: var(--surface);
  color: var(--text);
  padding: 8px 14px;
  border-radius: 8px;
  border: 1px solid var(--border-strong);
  z-index: 100;
  text-decoration: none;
  transition: top 0.15s ease;
}
.skip-link:focus {
  top: 12px;
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
  border-radius: 6px;
}

/* Header */
.site-header {
  border-bottom: 1px solid var(--border);
  background: rgba(11, 13, 18, 0.7);
  backdrop-filter: saturate(140%) blur(8px);
  position: sticky;
  top: 0;
  z-index: 5;
}
.site-header nav {
  max-width: 1100px;
  margin: 0 auto;
  padding: 14px 22px;
  display: flex;
  align-items: center;
  gap: 24px;
}
.brand {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--text);
  text-decoration: none;
  font-weight: 700;
  letter-spacing: 0.2px;
}
.brand svg { color: var(--accent); }
.nav-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  gap: 6px;
}
.nav-list a {
  display: inline-block;
  padding: 8px 12px;
  color: var(--text-muted);
  text-decoration: none;
  border-radius: 8px;
  font-size: 0.95rem;
}
.nav-list a:hover { color: var(--text); background: var(--bg-elev-2); }
.nav-list a[aria-current="page"] {
  color: var(--text);
  background: var(--bg-elev-2);
  box-shadow: inset 0 0 0 1px var(--border);
}

/* Preview */
.preview {
  max-width: 1100px;
  margin: 0 auto;
  padding: 32px 22px 64px;
}
.card {
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.03) inset, 0 12px 30px rgba(0, 0, 0, 0.35);
}
.media { margin: 0; }
.media img {
  display: block;
  width: 100%;
  height: auto;
  max-height: 70vh;
  object-fit: cover;
  background: #000;
}
.meta {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  align-items: center;
  justify-content: space-between;
  padding: 18px 20px;
  border-top: 1px solid var(--border);
  background: linear-gradient(180deg, var(--bg-elev), var(--bg-elev-2));
}
.meta-text h2 {
  margin: 0 0 4px;
  font-size: 1.15rem;
  font-weight: 600;
}
.sub {
  margin: 0;
  color: var(--text-muted);
  font-size: 0.9rem;
}
.actions {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 9px 14px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-strong);
  background: var(--surface);
  color: var(--text);
  font: inherit;
  font-size: 0.92rem;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease, color 0.15s ease, transform 0.05s ease;
  /* transparent outline lets focus render in forced colors */
  outline: 2px solid transparent;
  outline-offset: 2px;
}
.btn:hover { background: #232838; border-color: #4a5470; }
.btn:active { transform: translateY(1px); }
.btn:focus-visible { outline-color: var(--focus); }

.btn.ghost { background: transparent; }
.btn.ghost:hover { background: var(--bg-elev-2); }

.btn.danger {
  color: var(--danger-strong);
  border-color: #5a2330;
  background: rgba(255, 106, 120, 0.06);
}
.btn.danger:hover {
  background: rgba(255, 106, 120, 0.14);
  border-color: #7a2e3f;
  color: #ffb1ba;
}
.btn.danger.solid {
  color: #fff;
  background: linear-gradient(180deg, #e64759, #c8364a);
  border-color: #b8324a;
}
.btn.danger.solid:hover {
  background: linear-gradient(180deg, #ee5263, #d23c52);
}

.btn[disabled],
.btn[aria-disabled="true"] {
  opacity: 0.65;
  cursor: not-allowed;
}

/* Dialog */
.dialog-root {
  position: fixed;
  inset: 0;
  display: grid;
  place-items: center;
  padding: 20px;
  z-index: 50;
}
.dialog-root[hidden] { display: none; }

.dialog-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(4, 6, 10, 0.66);
  backdrop-filter: blur(4px);
  animation: fade 0.16s ease-out;
}

.dialog-panel {
  position: relative;
  width: min(440px, 100%);
  background: var(--bg-elev);
  color: var(--text);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius);
  padding: 24px 24px 20px;
  box-shadow: var(--shadow-lg);
  animation: pop 0.18s ease-out;
}

.dialog-icon {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  color: var(--danger-strong);
  background: var(--danger-bg);
  border: 1px solid #5a2330;
  margin-bottom: 14px;
}

.dialog-title {
  margin: 0 0 6px;
  font-size: 1.15rem;
  font-weight: 600;
  letter-spacing: 0.1px;
}
.dialog-desc {
  margin: 0 0 18px;
  color: var(--text-muted);
  font-size: 0.95rem;
}

.dialog-status {
  min-height: 0;
  font-size: 0.88rem;
  color: var(--text-muted);
}
.dialog-status:not(:empty) {
  margin: 0 0 12px;
  padding: 8px 10px;
  border-radius: 8px;
  background: var(--bg-elev-2);
  border: 1px solid var(--border);
}

.dialog-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 8px;
  flex-wrap: wrap;
}

.dialog-close {
  position: absolute;
  top: 10px;
  right: 10px;
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
  border-radius: 8px;
  background: transparent;
  color: var(--text-muted);
  border: 1px solid transparent;
  cursor: pointer;
  outline: 2px solid transparent;
  outline-offset: 2px;
}
.dialog-close:hover { background: var(--bg-elev-2); color: var(--text); border-color: var(--border); }
.dialog-close:focus-visible { outline-color: var(--focus); }

@keyframes fade { from { opacity: 0; } to { opacity: 1; } }
@keyframes pop {
  from { opacity: 0; transform: translateY(6px) scale(0.98); }
  to   { opacity: 1; transform: translateY(0)    scale(1); }
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  .dialog-backdrop, .dialog-panel { animation: none; }
  .skip-link { transition: none; }
}

/* Forced colors */
@media (forced-colors: active) {
  .btn,
  .dialog-panel,
  .dialog-close {
    border-color: ButtonBorder;
    color: ButtonText;
    background: ButtonFace;
  }
  .dialog-backdrop { background: Canvas; opacity: 0.7; }
  .btn:focus-visible,
  .dialog-close:focus-visible { outline-color: Highlight; }
  .dialog-icon { background: Canvas; color: ButtonText; border-color: ButtonBorder; }
}

/* Reflow */
@media (max-width: 480px) {
  .meta { flex-direction: column; align-items: flex-start; }
  .actions { width: 100%; }
  .actions .btn { flex: 1; justify-content: center; }
  .dialog-actions .btn { flex: 1; justify-content: center; }
}
